import shutil
import openpyxl
from openpyxl.styles import PatternFill

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def is_nonzero(value):
    if value is None:
        return False
    try:
        return float(value) != 0.0
    except (TypeError, ValueError):
        s = str(value).strip()
        return s != "" and s.lower() not in {"0", "0.0"}

nonzero_types = []
for row in range(2, 28):
    qty = vws.cell(row=row, column=2).value
    if not is_nonzero(qty):
        continue

    typ = vws.cell(row=row, column=1).value
    if typ is None:
        continue

    if isinstance(typ, str):
        typ = typ.strip()
        if typ == "":
            continue

    nonzero_types.append(typ)

fill = PatternFill(start_color="92D050", end_color="92D050", fill_type="solid")

for i in range(26):
    cell = ws.cell(row=2 + i, column=8)
    if i < len(nonzero_types):
        cell.value = nonzero_types[i]
    else:
        cell.value = None
    cell.fill = fill

print("nonzero_count:", len(nonzero_types))
print("first_values:", nonzero_types[:5])

wb.save(OUT)
